static void ggml_compute_forward(struct ggml_compute_params * params, struct ggml_tensor * tensor) {
    GGML_ASSERT(params);

    if (tensor->op == GGML_OP_NONE || ggml_is_empty(tensor)) {
        return;
    }

#if defined(__riscv) && defined(ANDESIM_ROI_MUL_MAT_K)
    // count MUL_MAT nodes HERE, before the extra-buffer dispatch: repacked
    // weights (e.g. Q1_0 64x1) are handled by tensor traits and return
    // early, so counting inside the switch below would skip them
    static int andesim_mul_mat_n = 0;
    // resolved once; single-threaded like the counter above (the runbook uses -t 1)
    static int andesim_roi_first = 0, andesim_roi_last = 0;
    if (andesim_roi_first == 0) {
        andesim_roi_first = ggml_roi_node_index(getenv("GGML_ROI_MUL_MAT_K"), ANDESIM_ROI_MUL_MAT_K);
        andesim_roi_last  = andesim_roi_first +
                            ggml_roi_node_index(getenv("GGML_ROI_MUL_MAT_N"), ANDESIM_ROI_MUL_MAT_N) - 1;
#ifdef ANDESIM_ROI_CLEAR_DPREF
        // Experiment knob (opt-in -D, never on in a measurement build): clear
        // mcache_ctl.DPREF_EN, the Andes D-cache prefetch-unit enable that
        // crt0.S sets as part of its 0x703 mask. The Q1_0 gemv issues 18
        // prefetch.r per weight brick; if that stream is serviced by the D$
        // prefetch unit, disabling it must erase the measured gain. Printing
        // the CSR is the check that matters -- an engine that WARLs the bit
        // leaves it set and the whole A/B would be void with no other symptom.
        {
            uint64_t before, after;
            __asm__ volatile("csrr %0, 0x7CA" : "=r"(before));
            __asm__ volatile("csrc 0x7CA, %0" :: "r"((uint64_t) 0x400));
            __asm__ volatile("csrr %0, 0x7CA" : "=r"(after));
            fprintf(stderr, "[roi] mcache_ctl 0x%llx -> 0x%llx : DPREF_EN %d -> %d\n",
                    (unsigned long long) before, (unsigned long long) after,
                    (int) ((before >> 10) & 1), (int) ((after >> 10) & 1));
        }
#endif
    }
    const bool andesim_roi_mm = tensor->op == GGML_OP_MUL_MAT;
    if (andesim_roi_mm) {
        ++andesim_mul_mat_n;
        if (andesim_mul_mat_n == andesim_roi_first) {
            // identify the measured node so a weights-in-HVM run can confirm
            // it relocated the right src0 (name + dims must match the target)
            fprintf(stderr, "[roi] MUL_MAT #%d src0=%s [%lld x %lld] nrows=%lld\n", andesim_mul_mat_n,
                    tensor->src[0]->name, (long long) tensor->src[0]->ne[0], (long long) tensor->src[0]->ne[1],
                    (long long) tensor->src[1]->ne[1]);
            andesim_ROI_begin();
        }
    }
#endif

    // extra_buffer op?
    if (ggml_cpu_extra_compute_forward(params, tensor)) {
#if defined(__riscv) && defined(ANDESIM_ROI_MUL_MAT_K)
        if (andesim_roi_mm && andesim_mul_mat_n == andesim_roi_last)
            andesim_ROI_end();
#endif
        return;
    }

    switch (tensor->op) {
        case GGML_OP_DUP:
            {
                ggml_compute_forward_dup(params, tensor);
                ggml_compute_forward_rms_norm_back(params, tensor);
            } break;
        case GGML_OP_GROUP_NORM:
            {
                ggml_compute_forward_group_norm(params, tensor);
            } break;
        case GGML_OP_L2_NORM:
            {
                ggml_compute_forward_l2_norm(params, tensor);
            } break;
        case GGML_OP_MUL_MAT:
            {
                ggml_compute_forward_mul_mat(params, tensor);
#if defined(__riscv) && defined(ANDESIM_ROI_MUL_MAT_K)
                if (andesim_mul_mat_n == andesim_roi_last)
                    andesim_ROI_end();
#endif
            } break;
        case GGML_OP_MUL_MAT_ID:
            {
                ggml_compute_forward_mul_mat_id(params, tensor);
            } break;
        case GGML_OP_OUT_PROD:
            {
                ggml_compute_forward_out_prod(params, tensor);
            } break;

